package assets

import (
	"archive/zip"
	"bytes"
	"encoding/base64"
)

// Graphics, fonts, levels and sound are Go-embedded game data. No executable is included.
var Files = bundledFiles()

func bundledFiles() *zip.Reader {
	data, err := base64.StdEncoding.DecodeString(packedResources)
	if err != nil {
		panic(err)
	}
	files, err := zip.NewReader(bytes.NewReader(data), int64(len(data)))
	if err != nil {
		panic(err)
	}
	return files
}

